declare(strict_types=1);

/*
 * Regenerates the small source files used by the import reader tests:
 * php tests/Import/Fixtures/generate.php
 *
 * All data is synthetic (example.com). Large files are generated by the tests
 * themselves into a temporary directory.
 */

use OpenSpout\Common\Entity\Cell;
use OpenSpout\Common\Entity\Row;
use OpenSpout\Common\Entity\Style\Style;
use OpenSpout\Writer\XLSX\Writer;

require __DIR__.'/../../../vendor/autoload.php';

$directory = __DIR__;

$contacts = [
    ['Company name', 'Registration number', 'Email', 'City', 'Note'],
    ['Example Company', '12345687', 'testing@example.com', 'Ústí nad Labem', 'Příliš žluťoučký kůň'],
    ['Example Trade', '12345687', 'trade@example.com', 'Ostrava', ''],
    ['Example Studio', '', 'studio@example.com', 'Praha', 'Quoted "value", with comma'],
];

// An iDoklad style export: UTF-8 with BOM, comma, LF, one header row.
$handle = fopen($directory.'/contacts-utf8-bom.csv', 'wb');
if (false === $handle) {
    throw new RuntimeException('Cannot write the fixture.');
}
fwrite($handle, "\xEF\xBB\xBF");
foreach ($contacts as $record) {
    fputcsv($handle, $record, ',', '"', '', "\n");
}
fclose($handle);

// A Czech accounting tool export: Windows-1250, semicolon, CRLF, two title rows above the header.
$lines = ['Example Company export;;;;', 'Generated 2026-10-01;;;;'];
foreach ($contacts as $record) {
    $lines[] = implode(';', array_map(
        static fn (string $cell): string => str_contains($cell, ';') || str_contains($cell, '"') || str_contains($cell, ',')
            ? '"'.str_replace('"', '""', $cell).'"'
            : $cell,
        $record,
    ));
}
file_put_contents(
    $directory.'/contacts-windows-1250.csv',
    iconv('UTF-8', 'CP1250', implode("\r\n", $lines)."\r\n"),
);

/**
 * @param list<list<string>> $records
 *
 * @return list<Row>
 */
function sheetRows(array $records): array
{
    $rows = [];
    foreach ($records as $record) {
        $rows[] = Row::fromValues($record);
    }

    return $rows;
}

// Two sheets, header on row 1 of each.
$writer = new Writer();
$writer->openToFile($directory.'/two-sheets.xlsx');
$writer->getCurrentSheet()->setName('Contacts');
$writer->addRows(sheetRows($contacts));
$writer->addNewSheetAndMakeItCurrent()->setName('Archive');
$writer->addRows(sheetRows([['Company name', 'Closed'], ['Example Old', 'yes']]));
$writer->close();

// Numeric and date cells.
$writer = new Writer();
$writer->openToFile($directory.'/numbers-and-dates.xlsx');
$writer->addRow(Row::fromValues(['Id', 'Amount', 'Date']));
$writer->addRow(new Row([
    Cell::fromValue(1234567),
    Cell::fromValue(0.5),
    Cell::fromValue(new DateTimeImmutable('2026-10-01'), new Style()->setFormat('yyyy-mm-dd')),
]));
$writer->close();
